use crate::DbPool;
use sqlx::{Postgres, QueryBuilder};
use uuid::Uuid;

#[derive(Debug, Clone)]
pub struct JobSearchHit {
    pub job_id: Uuid,
    pub score: f32,
}

#[derive(Debug, Clone)]
pub struct JobSearchPage {
    pub hits: Vec<JobSearchHit>,
    pub total_count: usize,
}

/// Job search backed by Postgres full-text search (`jobs.search_vector`,
/// see migration 013) instead of a Tantivy index on disk. The tsvector
/// column is generated by Postgres itself on every insert/update, so there
/// is nothing here to open, write, or rebuild — just query.
pub struct JobSearchIndex {
    pool: DbPool,
}

impl JobSearchIndex {
    pub fn new(pool: DbPool) -> Self {
        Self { pool }
    }

    pub async fn search(
        &self,
        query_text: Option<&str>,
        location: Option<&str>,
        page: i64,
        limit: i64,
    ) -> Result<JobSearchPage, Box<dyn std::error::Error + Send + Sync>> {
        let page = page.max(1);
        let limit = limit.clamp(1, 200);
        let offset = (page - 1) * limit;

        let q = query_text.map(str::trim).filter(|s| !s.is_empty());
        let loc = location.map(str::trim).filter(|s| !s.is_empty());

        let mut select_qb: QueryBuilder<Postgres> = QueryBuilder::new("SELECT id, ");
        let mut count_qb: QueryBuilder<Postgres> =
            QueryBuilder::new("SELECT COUNT(*) FROM jobs WHERE status = 'active'");

        if let Some(q) = q {
            // normalization = 32 -> rank / (rank + 1), so score always lands in [0, 1);
            // callers (e.g. suggestions::refresh_keyword_suggestions) rely on that range.
            select_qb.push("ts_rank(search_vector, websearch_to_tsquery('english', ");
            select_qb.push_bind(q);
            select_qb.push(
                "), 32) AS score FROM jobs WHERE status = 'active' AND search_vector @@ websearch_to_tsquery('english', ",
            );
            select_qb.push_bind(q);
            select_qb.push(")");

            count_qb.push(" AND search_vector @@ websearch_to_tsquery('english', ");
            count_qb.push_bind(q);
            count_qb.push(")");
        } else {
            select_qb.push("0::real AS score FROM jobs WHERE status = 'active'");
        }

        if let Some(loc) = loc {
            let pattern = format!("%{loc}%");
            select_qb.push(" AND location ILIKE ");
            select_qb.push_bind(pattern.clone());
            count_qb.push(" AND location ILIKE ");
            count_qb.push_bind(pattern);
        }

        select_qb.push(" ORDER BY ");
        select_qb.push(if q.is_some() {
            "score DESC, posted_at DESC"
        } else {
            "featured DESC, posted_at DESC"
        });
        select_qb.push(" LIMIT ");
        select_qb.push_bind(limit);
        select_qb.push(" OFFSET ");
        select_qb.push_bind(offset);

        let rows: Vec<(Uuid, f32)> = select_qb
            .build_query_as::<(Uuid, f32)>()
            .fetch_all(&self.pool)
            .await?;
        let total_count: (i64,) = count_qb
            .build_query_as::<(i64,)>()
            .fetch_one(&self.pool)
            .await?;

        let hits = rows
            .into_iter()
            .map(|(job_id, score)| JobSearchHit { job_id, score })
            .collect();

        Ok(JobSearchPage {
            hits,
            total_count: total_count.0 as usize,
        })
    }
}
